import json, os, pathlib, subprocess, tempfile, time
REPO=pathlib.Path('/Users/edo/dev/python/journal')
BASE=pathlib.Path(tempfile.mkdtemp(prefix='journal-generic-memory-'))
VAULT=BASE/'vault'; VAULT.mkdir()
OUT=BASE/'evidence'; OUT.mkdir()
(VAULT/'course-overview.md').write_text('''# Signals Studio\nWorking course material list supplied by the lecturer:\n- Lumen: lecture notes, organised as response, stability, frequency.\n- Atlas: reference textbook with longer derivations.\n- Lab sheets: laboratory questions.\nThis list gives no prerequisite ordering, edition status or assessment format.\n''')
env=dict(os.environ)
for key in list(env):
    if key.endswith('_API_KEY') or key in {'ANTHROPIC_AUTH_TOKEN','ANTHROPIC_OAUTH_TOKEN','AWS_BEARER_TOKEN_BEDROCK'}: env.pop(key,None)
env.update(VAULT_DIR=str(VAULT),LEARNING_ROOT=str(VAULT/'learn'),LEARNING_ASSETS=str(VAULT/'assets/learn'),LEARNING_SESSION_DIR=str(BASE/'sessions'),LEARNING_PYTHON=str(REPO/'.venv/bin/python'),LEARNING_PACKAGE=str(REPO),LEARNING_OPEN='0',PI_OFFLINE='1')
boundary=f'Use the canonical learn skill at {REPO}/learning/skills/learn/SKILL.md and its actual tools. This is an isolated synthetic study vault: {VAULT}. Environment variables already point to it. Read course sources and write learner state only in this vault. Do not access real learner data, edit repository or configuration, open GUI, browse or spawn agents. Answer the learner normally.\n\n'
prompts=[
"Let's get our bearings for Signals Studio; the available resources are in course-overview.md. I suspect response and stability are two ways of looking at the same ideas rather than separate modules, but I'm not sure yet. In the lecturer's notation g is the impulse response; Atlas calls that h. The old lab sheets seem to track the lecturer's assumptions closely, whereas Atlas is more useful for derivations. Help me form a rough picture. I don't want a fixed curriculum, an exercise or a quiz right now, and I've not demonstrated understanding of the material yet.",
"Back to Signals Studio. I checked with the lecturer: response and stability are recurring viewpoints; the frequency chapter revisits both, rather than being a third independent module. Also, my earlier impression of the old lab sheets was misleading: those sheets assume continuous time, while the current lab is discrete time. Use Lumen for the current conventions; Atlas still helps with derivations. These are corrections to our understanding of the course and resources, not evidence that I've learnt the mathematics. Explain briefly how this changes our picture, without starting an exercise.",
"Back to Signals Studio in this new conversation. Before we tackle the next lab, how should I navigate the resources and connect the response, stability and frequency material? Remind me of any notation mismatch we had noticed. Keep the picture provisional where necessary; don't infer my mathematical ability from having discussed the course."
]
def clean(x):
    if isinstance(x,dict):
        if x.get('type') in {'thinking','reasoning'}: return None
        return {k:clean(v) for k,v in x.items() if not any(w in k.lower() for w in ['thinking','reasoning','signature'])}
    if isinstance(x,list): return [clean(v) for v in x if clean(v) is not None]
    return x
(OUT/'fixture.md').write_bytes((VAULT/'course-overview.md').read_bytes())
(OUT/'environment.json').write_text(json.dumps({'root':str(BASE),'baseline':subprocess.check_output(['git','rev-parse','HEAD'],cwd=REPO,text=True).strip()},indent=2))
print(str(BASE),flush=True)
for n,prompt in enumerate(prompts,1):
    cmd=['pi','--provider','openai-codex','--offline','--no-context-files','--no-extensions','--no-skills','--no-prompt-templates','--extension',str(REPO/'learning/pi.ts'),'--skill',str(REPO/'learning/skills/learn'),'--tools','read,bash,edit,write,grep,find,ls,learning_context,learning_save,correct_lesson','--no-session','--no-approve','--print','--mode','json',boundary+prompt]
    start=time.monotonic()
    run=subprocess.run(cmd,cwd=VAULT,env=env,text=True,capture_output=True,timeout=240)
    events=[]
    for line in run.stdout.splitlines():
        try: e=json.loads(line)
        except json.JSONDecodeError: continue
        if e.get('type') in {'message_end','tool_execution_start','tool_execution_end'}: events.append(clean(e))
    (OUT/f'{n}.prompt.txt').write_text(boundary+prompt)
    (OUT/f'{n}.trace.jsonl').write_text(''.join(json.dumps(e,ensure_ascii=False)+'\n' for e in events))
    answer=[]; usage=[]
    for e in events:
        m=e.get('message',{})
        if m.get('role')=='assistant':
            answer += [v['text'] for v in m.get('content',[]) if v.get('type')=='text']
            if m.get('usage'): usage.append({'model':m.get('model'),'provider':m.get('provider'),'usage':m['usage']})
    (OUT/f'{n}.answer.md').write_text('\n\n'.join(answer))
    state={str(p.relative_to(VAULT)):json.loads(p.read_text()) for p in (VAULT/'learn/state').glob('*.json')}
    (OUT/f'{n}.state.json').write_text(json.dumps(state,indent=2))
    metric={'seconds':round(time.monotonic()-start,2),'returncode':run.returncode,'calls':sum(e.get('type')=='tool_execution_start' for e in events),'usage':usage}
    (OUT/f'{n}.metrics.json').write_text(json.dumps(metric,indent=2))
    print(json.dumps({'turn':n,**{k:v for k,v in metric.items() if k!='usage'},'state_keys':list(state)}),flush=True)
    if run.returncode: print(run.stderr[-1000:],flush=True); break

